import csv
import math

def log1p(x):
    return math.log1p(x)

def solve():
    t09_path = 'outputs/t09_poi_nearest_stop.csv'
    t06_path = 'outputs/t06_stop_service_intensity.csv'

    t06_data = {}
    with open(t06_path, mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            t06_data[row['stop_id']] = {
                'n_departures': int(row['n_departures']),
                'n_routes': int(row['n_routes'])
            }

    max_log_deps = -1.0
    max_log_routes = -1.0

    # First pass to find maxes
    with open(t09_path, mode='r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            stop_id = row['nearest_stop_id']
            if stop_id in t06_data:
                n_deps = t06_data[stop_id]['n_departures']
                n_routes = t06_data[stop_id]['n_routes']
                log_deps = log1p(n_deps)
                log_routes = log1p(n_routes)
                if log_deps > max_log_deps:
                    max_log_deps = log_deps
                if log_routes > max_log_routes:
                    max_log_routes = log_routes

    print(f"max_log_deps: {max_log_deps}")
    print(f"max_log_routes: {max_log_routes}")

solve()
